def kanten(schedule):
    ops = [(s[0], s[1], s[3])
           for s in schedule.split()]
    k = set()
    for i, (a1, t1, x1) in enumerate(ops):
        for a2, t2, x2 in ops[i+1:]:
            if (t1 != t2 and x1 == x2
                    and "w" in a1 + a2):
                k.add((t1, t2))
    return k

def zyklus(k):
    while k:
        ziele = {z for _, z in k}
        quellen = {q for q, _ in k} - ziele
        if not quellen:
            return True
        k = {(q, z) for q, z in k
             if q not in quellen}
    return False

for s in ["r1(x) r2(x) w1(x) w2(x)",
          "r1(x) w1(x) r2(x) w2(x)"]:
    k = kanten(s)
    print(sorted(k), zyklus(k))

